python3 -I - <<'PY'
import json, glob, os, time, collections
files = sorted(glob.glob(os.path.expanduser("~/.claude/projects/*/*.jsonl")), key=os.path.getmtime, reverse=True)[:50]
if files:
    days = (time.time()-os.path.getmtime(files[-1]))/86400
    print(f"window: {len(files)} sessions, ~{days:.0f} days")
tools = collections.Counter(); skills = collections.Counter(); cmds = collections.Counter()
hooks = collections.defaultdict(list); timeouts = collections.Counter()
denials = collections.Counter(); kinds = collections.defaultdict(collections.Counter)
pending = {}
for f in files:
    try:
        for line in open(f, encoding="utf-8", errors="replace"):
            try: o = json.loads(line)
            except Exception: continue
            t = o.get("type"); m = o.get("message") or {}
            c = m.get("content") if isinstance(m, dict) else None
            if t == "assistant" and isinstance(c, list):
                for b in c:
                    if isinstance(b, dict) and b.get("type") == "tool_use":
                        n = b.get("name",""); tools[n]+=1
                        inp = b.get("input") or {}
                        if n == "Skill": skills[str(inp.get("skill",""))]+=1
                        if n == "Bash":
                            parts = str(inp.get("command","")).split()
                            key = " ".join(parts[:2]) if parts else ""
                            pending[b.get("id")] = ("Bash", key)
                        else:
                            pending[b.get("id")] = (n, n)
            if t == "user":
                if isinstance(c, str) and "<command-name>" in c:
                    import re
                    for mm in re.findall(r"<command-name>/?([^<]+)</command-name>", c): cmds[mm]+=1
                if "toolDenialKind" in o:
                    kind = o["toolDenialKind"]
                    if kind in ("interrupted","cancelled"): continue
                    tid = None
                    if isinstance(c, list):
                        for b in c:
                            if isinstance(b, dict) and b.get("type")=="tool_result": tid=b.get("tool_use_id")
                    name, key = pending.get(tid, ("?","?"))
                    denials[(name,key)]+=1; kinds[(name,key)][kind]+=1
            if t == "attachment":
                a = o.get("attachment") or {}
                if str(a.get("type","")).startswith("hook_"):
                    hn = f"{a.get('hookEvent')}:{a.get('hookName')}"
                    if a.get("type")=="hook_cancelled" and a.get("timedOut"): timeouts[hn]+=1
                    if isinstance(a.get("durationMs"),(int,float)): hooks[hn].append(a["durationMs"])
    except Exception as e:
        pass
print("== MCP tool calls (normalized names)")
for n,c in tools.most_common():
    if n.startswith("mcp__"): print(c, n)
print("== Skill tool invocations")
for n,c in skills.most_common(): print(c, n)
print("== slash commands")
for n,c in cmds.most_common(): print(c, n)
print("== hook timing (n, median ms, max ms, timeouts)")
import statistics
for hn,v in sorted(hooks.items(), key=lambda kv:-max(kv[1])):
    print(len(v), int(statistics.median(v)), int(max(v)), timeouts.get(hn,0), hn)
for hn,c in timeouts.items():
    if hn not in hooks: print(0,0,0,c,hn)
print("== denials (count, kind mix)")
for k,c in denials.most_common(25):
    print(c, k[0], k[1], dict(kinds[k]))
print("total denial entries", sum(denials.values()))
PY

